import{_ as a,o,c as t,a2 as i}from"./chunks/framework.Bum8orMG.js";const h=JSON.parse('{"title":"Roadmap","description":"What is planned for KatanaKit. Contributions welcome.","frontmatter":{"title":"Roadmap","description":"What is planned for KatanaKit. Contributions welcome."},"headers":[],"relativePath":"guides/roadmap.md","filePath":"guides/roadmap.md","lastUpdated":1790432985000}'),d={name:"guides/roadmap.md"};function r(c,e,s,n,l,p){return o(),t("div",null,[...e[0]||(e[0]=[i('<p>A living list of what is planned for KatanaKit (<code>katanakit-js</code>). Contributions are welcome — pick something and open a pull request.</p><p>Legend: <code>[x]</code> done · <code>[ ]</code> planned.</p><h2 id="shipped-as-of-2-2-1" tabindex="-1">Shipped (as of 2.2.1) <a class="header-anchor" href="#shipped-as-of-2-2-1" aria-label="Permalink to &quot;Shipped (as of 2.2.1)&quot;">​</a></h2><h3 id="architecture-and-packaging" tabindex="-1">Architecture and packaging <a class="header-anchor" href="#architecture-and-packaging" aria-label="Permalink to &quot;Architecture and packaging&quot;">​</a></h3><ul><li>[x] Hexagonal reorganization into <code>types/</code>, <code>core/services/</code>, <code>infrastructure/</code>, <code>adapters/</code>, <code>config/</code>.</li><li>[x] Pure ESM: relative imports with explicit <code>.js</code> extensions, <code>module: nodenext</code>, <code>&quot;type&quot;: &quot;module&quot;</code> and an <code>exports</code> map with subpaths (<code>katanakit-js/adapters/express</code>, <code>katanakit-js/adapters/nuxt</code>).</li><li>[x] <code>use*</code> method convention across every service (only <code>getInstance()</code> is exempt).</li><li>[x] Destructured, tree-shakeable exports from Singleton facades.</li><li>[x] Single source of truth for contracts and domain types in <code>src/types/</code>.</li><li>[x] No side effects on import; SSR-safe infrastructure adapters.</li><li>[x] Removed TypeScript errors, import-time side effects and duplicate types.</li><li>[x] Dependency restructure: only <code>@js-temporal/polyfill</code> as a runtime dependency; <code>express</code>, <code>cors</code>, <code>dotenv</code> and <code>vue</code> as optional peer dependencies.</li><li>[x] Package renamed for publication as <code>katanakit-js</code> (previously developed as <code>katanakit-dev</code>).</li></ul><h3 id="services-and-adapters" tabindex="-1">Services and adapters <a class="header-anchor" href="#services-and-adapters" aria-label="Permalink to &quot;Services and adapters&quot;">​</a></h3><ul><li>[x] Core services: HTTP client, logger, formatter, converter, errors, generator, dates (Temporal), geometry, timing, data/system utilities and the reactive signals kernel.</li><li>[x] Infrastructure adapters: DOM, storage, viewport, sensors, observer (+ lazy loader), worker (+ pools) and theme.</li><li>[x] Astro adapter (<code>AstroService</code>) for <code>getStaticPaths</code>.</li><li>[x] RSS service (<code>RssService</code>) with raw XML generation and Astro <code>GET</code> endpoints — no external dependencies.</li><li>[x] Site config (<code>SiteConfig</code>/<code>siteConfig</code>) and SEO module (<code>useHeadTags</code>, <code>useGenerateMetaTags</code>, <code>useTitle</code>, <code>useRssHeadLink</code>).</li><li>[x] Nuxt adapter (<code>katanakit-js/adapters/nuxt</code>): <code>useUnwrap</code>, <code>useSafeResponse</code>, <code>useEventResponse</code>.</li><li>[x] Vue adapter (<code>katanakit-js/adapters/vue</code>): <code>useRequest</code> composable (<code>data</code>, <code>error</code>, <code>loading</code>, <code>refetch</code>).</li><li>[x] Express reference server (<code>katanakit-js/adapters/express</code>) with CORS restriction defaults and hardened headers.</li><li>[x] Worker pool concurrency fixed by correlating tasks with a <code>taskId</code> echo.</li><li>[x] <code>useEncrypt</code> generates a random salt when none is provided.</li></ul><h3 id="quality-and-tooling" tabindex="-1">Quality and tooling <a class="header-anchor" href="#quality-and-tooling" aria-label="Permalink to &quot;Quality and tooling&quot;">​</a></h3><ul><li>[x] Vitest suite: 60 tests across 8 files (http, logger, storage, core, rss, nuxt, seo, vue) with the <code>@/</code> alias.</li><li>[x] ESLint + Prettier lint + format wired (<code>lint</code>, <code>check</code>, <code>format</code> scripts).</li><li>[x] <code>release:patch|minor|major|beta</code> scripts with a <code>validate</code> gate (check + test + build).</li><li>[x] English documentation: README, Getting Started, Architecture, API Reference, Roadmap, CONTRIBUTING, SECURITY, CHANGELOG.</li><li>[x] Security fixes applied: URL scheme validation, DOM <code>on*</code> attribute block, JSON-LD <code>&lt;/script&gt;</code> escaping, worker cleanup, generic server errors.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li>[ ] <strong>Publish <code>katanakit-js</code> 2.2.1 to npm</strong> (the package is renamed and versioned but not yet released).</li><li>[ ] HTTP client: request interceptors, retry with backoff, request cancellation (<code>AbortSignal</code>) and a caching layer (stale-while-revalidate).</li><li>[ ] Reactive: automatic dependency tracking for <code>useCreateEffect</code>/<code>useCreateMemo</code>.</li><li>[ ] More framework adapters: React hooks (<code>useApi</code>, <code>useSignal</code>) and Svelte stores.</li><li>[ ] Structured/JSON logger strategy.</li><li>[ ] Add Vitest coverage reporting and a CI pipeline (GitHub Actions) running <code>check</code>, <code>test</code> and <code>build</code> on the <code>dev</code> branch.</li></ul><h2 id="later" tabindex="-1">Later <a class="header-anchor" href="#later" aria-label="Permalink to &quot;Later&quot;">​</a></h2><ul><li>[ ] UI kit (Katana UI) — tokens, headless primitives, layouts and app pages. See the <a href="./../ui-kit/">UI Kit section</a>.</li><li>[ ] Deno / Cloudflare Workers compatibility pass.</li><li>[ ] More geometry (3D solids) and unit-system conversions.</li><li>[ ] i18n and relative-time output for <code>DatesService.useDiff</code>.</li><li>[ ] E2E tests for the Express adapter.</li><li>[ ] AbortController support in <code>useInterval</code>/timeout helpers.</li></ul>',13)])])}const g=a(d,[["render",r]]);export{h as __pageData,g as default};
